select from oa_sign_package where package_id in
#{packageId}
order by package_id desc

select ,
       (select count(*)
        from oa_sign_package_document document_count_row
        where document_count_row.package_id = oa_sign_package.package_id) as document_count
from oa_sign_package


        and employee_name_snapshot like concat('%', #{employeeNameSnapshot}, '%')


        and (scenario = #{scenario}
             or (lower(#{scenario}) = 'renewal' and lower(trim(scenario)) = 'renew'))


        and status = #{status}


        and shop_dept_id = #{shopDeptId}


        and shop_dept_id in

            #{scopeDeptId}


    and (
        task_id is null
        or exists (
            select 1
            from oa_sign_task owner_task
            where owner_task.task_id = oa_sign_package.task_id
              and owner_task.package_id = oa_sign_package.package_id

              and owner_task.assigned_hr_user_id = #{params.assignedHrUserId}

        )
    )

order by package_id desc

select , (select count(*) from oa_sign_package_document document_count_row where document_count_row.package_id = oa_sign_package.package_id and document_count_row.employee_visible = 'Y') as document_count from oa_sign_package
employee_id = #{employeeId}
and status = #{status}
order by package_id desc

select facts.employee_id, latest_package.package_id as latest_package_id, latest_package.task_id as latest_task_id, latest_package.status as latest_status, latest_package.shop_dept_id as latest_shop_dept_id, signed_package.package_id as signed_package_id, signed_package.task_id as signed_task_id, signed_package.shop_dept_id as signed_shop_dept_id, case when signed_package.package_id is not null and signed_package.final_document_version is not null and trim(signed_package.final_document_version) != '' and signed_package.final_document_root_hash is not null and trim(signed_package.final_document_root_hash) != '' and signed_package.final_generated_time is not null and upper(trim(signed_package.final_confirmation_status)) = 'CONFIRMED' then 1 else 0 end as signed_evidence_complete from ( select employee_id, max(package_id) as latest_package_id, max(case when lower(trim(status)) = 'signed' then package_id end) as signed_package_id from oa_sign_package where upper(trim(scenario)) = 'ONBOARD' and employee_id in
#{employeeId}
group by employee_id ) facts inner join oa_sign_package latest_package on latest_package.package_id = facts.latest_package_id left join oa_sign_package signed_package on signed_package.package_id = facts.signed_package_id order by facts.employee_id asc

