update oa_sign_package
set status = 'voided',
    void_reason = #{voidReason},
    version = version + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where package_id = #{packageId}
  and status = #{currentStatus}
  and version = #{expectedVersion}
  and #{currentStatus} in (
      'draft', 'pending_sign', 'part_viewed', 'pending_company',
      'pending_final_confirm', 'failed'
  )
